var DATA = {"mode": "dataset", "name": "street-v3", "n": 50000};
function show(k,v){console.log(k+": "+v);}
var m=DATA.mode;
if(m==="install"){
  show("Install","pip install fiftyone");
  show("Launch","fiftyone app launch");
  show("License","Apache 2.0, open source");
}else if(m==="dataset"){
  show("Dataset",DATA.name);
  show("Samples",DATA.n);
  show("Lives","in MongoDB-backed local store");
