}else if(m==="embed"){
  show("Embeddings",DATA.n+" vectors x "+DATA.d+" dims");
  show("Use","similarity search, UMAP scatter");
}else if(m==="zoo"){
  show("Zoo","one-line datasets and models");
  show("Example","foz.load_zoo_dataset('quickstart')");
}else if(m==="plugin"){
  show("Plugins","custom App panels");
  show("Share","via the plugin hub");
}else if(m==="tag"){
  show("Tags","label sample subsets");
  show("Use","mark review queues, splits");
}else if(m==="export"){
  show("Export",DATA.fmt);
  show("Round-trip","to training frameworks");
}else if(m==="brain"){
  show("Brain methods","similarity, uniqueness, mistakenness");
  show("Finds","duplicates and mislabels");
}else if(m==="app"){
